input.script:
export const meta = {
  name: 'nyquist-validation-28-29-30-32',
  description: 'Author retroactive Nyquist VALIDATION.md for phases 28/29/30/32 (document current coverage), then spot-check each',
  phases: [
    { title: 'Validate', detail: 'gsd-nyquist-auditor per phase writes {NN}-VALIDATION.md' },
    { title: 'Spot-check', detail: 'independent skeptic confirms cited tests exist' },
  ],
}

const DATE = (args && args.date) || '2026-06-19'
const ROOT = '/Users/myankelev/Code/random/cipher-box'

const VAL_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['phase', 'reportPath', 'nyquistCompliant', 'framework', 'summary'],
  properties: {
    phase: { type: 'string' },
    reportPath: { type: 'string' },
    nyquistCompliant: { type: 'boolean' },
    framework: { type: 'string', description: 'test framework detected (jest / vitest / cargo / none)' },
    covered: { type: 'number' },
    partial: { type: 'number' },
    missing: { type: 'number' },
    manualOnly: { type: 'number' },
    gaps: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
}

const SKEPTIC_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['phase', 'verdict', 'claimsChecked', 'claimsConfirmed', 'notes'],
  properties: {
    phase: { type: 'string' },
    verdict: { type: 'string', enum: ['confirmed', 'minor-issues', 'refuted'] },
    claimsChecked: { type: 'number' },
    claimsConfirmed: { type: 'number' },
    issues: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
}

const PHASES = [
  { num: '28', dir: '.planning/phases/28-code-hygiene-logging', file: '28-VALIDATION.md', area: 'apps/api + apps/web (code hygiene / structured logging)' },
  { num: '29', dir: '.planning/phases/29-infrastructure-hardening', file: '29-VALIDATION.md', area: 'apps/api / infra (infrastructure hardening — orphaned-IPNS cleanup, test-login hardening)' },
  { num: '30', dir: '.planning/phases/30-web-app-observability', file: '30-VALIDATION.md', area: 'apps/web (Grafana Faro RUM, logger transport)' },
  { num: '32', dir: '.planning/phases/32-fuse-async-filepointer-resolution', file: '32-VALIDATION.md', area: 'crates/fuse + apps/desktop (Rust cargo tests)' },
]

function validate(p) {
  const prompt =
    'You are the gsd-nyquist-auditor subagent. Read ' + ROOT + '/.claude/agents/gsd-nyquist-auditor.md for your full instructions.\n\n' +
    'TASK: Author a RETROACTIVE Nyquist validation contract for the already-completed Phase ' + p.num + '. Write it to ' + ROOT + '/' + p.dir + '/' + p.file + '\n\n' +
    'PHASE_NUM=' + p.num + '\nPHASE_DIR=' + ROOT + '/' + p.dir + '\nArea: ' + p.area + '\n\n' +
    'Get the phase goal + success criteria + plan list:\n  node ' + ROOT + '/.claude/gsd-core/bin/gsd-tools.cjs query roadmap.get-phase ' + p.num + ' --raw\n' +
    'Then read all ' + p.dir + '/*-PLAN.md and *-SUMMARY.md to build the per-task / per-success-criterion map.\n\n' +
    'METHOD (State A reconstruction):\n' +
    '1. Detect the test framework + config + run commands for this area (jest at apps/api/jest.config.js, vitest at apps/web, or cargo for crates/fuse).\n' +
    '2. Build a per-task (or per-SC) verification map. For EACH requirement/SC, locate existing tests by filename/describe/test names via grep/read and classify: COVERED (green — a real test targets the behavior), PARTIAL, MISSING, or MANUAL-ONLY (with justification).\n' +
    '3. Reflect ACTUAL CURRENT coverage — these phases shipped, so use real status (green / manual), not "pending" stubs. Match the retroactive format of ' + ROOT + '/.planning/phases/18-performance-instrumentation/18-VALIDATION.md (validated, per-task map with real specs + test counts, Manual-Only table, a "## Validation Audit ' + DATE + '" note). For the Rust phase use the cargo style of ' + ROOT + '/.planning/phases/33-windows-async-filepointer-resolution/33-VALIDATION.md.\n' +
    '4. Frontmatter: phase, slug, status (set "validated" only if every SC/requirement has automated coverage OR justified manual-only; otherwise "draft"), nyquist_compliant (true only under that same condition — be honest), wave_0_complete: true (retroactive — no wave-0 stubs are outstanding), created: ' + DATE + '. Add an "## Validation Audit ' + DATE + '" section summarizing covered/partial/missing/manual counts and noting this is a retroactive documentation pass.\n\n' +
    'HARD CONSTRAINTS:\n' +
    '- STATIC ANALYSIS ONLY. Do NOT run any test suite (no pnpm test, jest, vitest, cargo test) — multiple auditors run in parallel and would starve RAM. Prove a test exists by enumeration (grep its describe/it/#[test] name or the file), never by executing it.\n' +
    '- Do NOT generate, write, or modify ANY test file or source file. The ONLY file you create is ' + p.file + '. This is a retroactive documentation pass on a docs branch.\n' +
    '- Do NOT git commit.\n' +
    '- Be honest: if real automated tests are absent for an SC, mark it MISSING or MANUAL-ONLY with justification and set nyquist_compliant accordingly — do not claim coverage that does not exist.\n\n' +
    'Return the structured summary via StructuredOutput (counts + nyquistCompliant + any gaps).'
  return agent(prompt, { label: 'validate:' + p.num, phase: 'Validate', agentType: 'gsd-nyquist-auditor', effort: 'high', schema: VAL_SCHEMA })
}

function skeptic(res, p) {
  const prompt =
    'Independent adversarial spot-check of a freshly written Nyquist VALIDATION.md. Do not trust it.\n\n' +
    'Read ' + ROOT + '/' + p.dir + '/' + p.file + '. For every row in its Per-Task Verification Map that claims a test EXISTS / is green (COVERED), independently confirm the cited test file and the named test actually exist in the repo (grep the file + the describe/it/#[test] name). Also sanity-check that the cited run command and framework/config paths are real. Flag any fabricated specs, wrong paths, or COVERED rows with no actual test, and check the nyquist_compliant flag is justified by what you find (no overclaiming).\n\n' +
    'Phase ' + p.num + ' area: ' + p.area + '. The report claims nyquistCompliant=' + (res && res.nyquistCompliant) + ', framework="' + (res && res.framework) + '".\n\n' +
    'STATIC ANALYSIS ONLY — do NOT run tests, do NOT write files. Return the structured verdict.'
  return agent(prompt, { label: 'check:' + p.num, phase: 'Spot-check', agentType: 'Explore', schema: SKEPTIC_SCHEMA })
}

const results = await pipeline(
  PHASES,
  (p) => validate(p),
  (res, p) => {
    if (!res) return { phase: p.num, file: p.file, dir: p.dir, validate: null, skeptic: null }
    return skeptic(res, p).then((s) => ({ phase: p.num, file: p.file, dir: p.dir, validate: res, skeptic: s }))
  }
)

return results
